import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 82 Monster or fish?","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 82 Monster or fish?","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 81 Escape","link":"/life/english/new-concept/book-2/unit-04/lesson-081"},"next":{"text":"第二册：实践与进步 · Lesson 83 After the elections","link":"/life/english/new-concept/book-2/unit-04/lesson-083"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 81 Escape","link":"/life/english/new-concept/book-2/unit-04/lesson-081"},"next":{"text":"第二册：实践与进步 · Lesson 83 After the elections","link":"/life/english/new-concept/book-2/unit-04/lesson-083"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-082.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-082.md"}'),i={name:"life/english/new-concept/book-2/unit-04/lesson-082.md"};function s(r,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-82-monster-or-fish" tabindex="-1">第二册：实践与进步 · Lesson 82 Monster or fish? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-82-monster-or-fish" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 82 Monster or fish?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>模糊影像可能被说成未知生物，讨论时应明确证据强弱；练习推测语气的梯度。本课的语言观察是：might have been 是对过去的不确定推测；must have been 是强推断，仍不是亲眼确认。不能因为照片模糊就把未知当成不存在或存在的证明。完成学习后，请写一段模糊照片分析，给出一种可能解释和仍缺少的信息。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>monster</td><td>/ˈmɒnstə/</td><td>n.</td><td>怪物</td><td>a sea monster</td></tr><tr><td>creature</td><td>/ˈkriːtʃə/</td><td>n.</td><td>生物</td><td>a strange creature</td></tr><tr><td>claim</td><td>/kleɪm/</td><td>n.</td><td>声称</td><td>check a claim</td></tr><tr><td>proof</td><td>/pruːf/</td><td>n.</td><td>证明</td><td>reliable proof</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>turn out to be — 最后证明是</li><li>beyond doubt — 毫无疑问，需要充分证据</li></ul><h2 id="语法讲解-情态动词的意义与形式" tabindex="-1">语法讲解：情态动词的意义与形式 <a class="header-anchor" href="#语法讲解-情态动词的意义与形式" aria-label="Permalink to &quot;语法讲解：情态动词的意义与形式&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：might have been 是对过去的不确定推测；must have been 是强推断，仍不是亲眼确认。不能因为照片模糊就把未知当成不存在或存在的证明。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The shape in the photograph might have been a large fish.</p></blockquote><p>照片中的轮廓可能是一条大鱼。</p><p>might have been 为对过去身份的推测，a large fish 为表语；might 表不确定，不是过去能力。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>might was 不合结构；过去推测用 might have been。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 might 以保留不确定性，读出 photograph 的重音在第一音节。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The shape in the photograph might have been a large fish. The photographer could not estimate its size. Researchers asked for the original image before commenting.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段模糊照片分析，给出一种可能解释和仍缺少的信息。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：might have been 为对过去身份的推测，a large fish 为表语；might 表不确定，不是过去能力。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：might was 不合结构；过去推测用 might have been。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全：It might ___ been a fish.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 情态动词对过去推测用 have 加过去分词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>研究者评论前要求什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The original image.</p><p><strong>解析：</strong> 他们先要原始资料，没有立即宣布发现新物种。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>might have been 与 must have been 哪个推断更强？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> must have been 更强。</p><p><strong>解析：</strong> must 表较强的逻辑推断，might 仅表示可能。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词的意义与形式。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-081">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-083">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
